package dashboard

import (
	"fmt"
	"io/fs"
	"net/http"
	"path"
	"strings"

	"github.com/integrio-intropy/intropy-cli/web"
)

// staticHandler serves the embedded SPA. Real build assets (hashed JS/CSS) are
// served with their correct content types; any path that does not map to a
// file falls back to index.html so the SPA's client-side routing works on deep
// links and reloads.
func staticHandler() (http.Handler, error) {
	sub, err := fs.Sub(web.Assets, "dist")
	if err != nil {
		return nil, fmt.Errorf("open embedded dashboard assets: %w", err)
	}
	index, err := fs.ReadFile(sub, "index.html")
	if err != nil {
		return nil, fmt.Errorf("embedded dashboard is missing index.html: %w", err)
	}
	fileServer := http.FileServerFS(sub)

	serveIndex := func(w http.ResponseWriter) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write(index)
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		name := path.Clean(strings.TrimPrefix(r.URL.Path, "/"))
		if name == "." || name == "" || name == "index.html" {
			serveIndex(w)
			return
		}
		if _, err := fs.Stat(sub, name); err != nil {
			serveIndex(w)
			return
		}
		fileServer.ServeHTTP(w, r)
	}), nil
}

// Package web embeds the built Intropy dashboard SPA so the CLI can serve it
// without any runtime dependency on Node or a Vite dev server.
//
// The embedded tree is the SPA's production build output (web/dist). A minimal
// placeholder dist/index.html is committed so `go build` and `go test` compile
// before the frontend has ever been built; a real `vite build` (see `make web`)
// overwrites it with the actual dashboard.
package web

import "embed"

// Assets holds the built SPA. It always contains dist/index.html; a full build
// adds the hashed JS/CSS bundles under dist/assets.
//
//go:embed all:dist
var Assets embed.FS

